# -*- coding: utf-8 -*-
"""
Single-file deployment launcher for the bundled Free Fire dashboard project.
On startup it restores the bundled Python modules and HTML template, then runs main.py.
Set PORT in Render/Railway; the application binds to 0.0.0.0.
"""
import base64
import json
import os
import pathlib
import zlib

BUNDLED_FILES = json.loads(r'{"main.py":"","dashboard_server.py":"","thunderFF_pb2.py":"","StartMatch_pb2.py":"","message_ids.py":"","CguTeam_pb2.py":"","CguFF_pb2.py":"","templates/index.html":""}')

ROOT = pathlib.Path(__file__).resolve().parent
for relative_path, encoded in BUNDLED_FILES.items():
    target = ROOT / relative_path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(zlib.decompress(base64.b64decode(encoded)))

# Run the bundled original entry point as __main__.
import runpy
os.chdir(ROOT)
runpy.run_path(str(ROOT / "main.py"), run_name="__main__")
